"""Root URL configuration (generated by Shikshya)."""
from django.conf import settings
from django.contrib import admin
from django.http import FileResponse, Http404, JsonResponse
from django.urls import include, path, re_path
from django.views.static import serve


def health_check(request):
    """Alive (config.middleware.HealthCheckMiddleware answers first; this route keeps the path in the URL map)."""
    return JsonResponse({"status": "ok"})


def frontend(request):
    """The built React app for every path that is not the API, the admin, health, static or media."""
    index = settings.FRONTEND_BUILD_DIR / "index.html"
    if not index.exists():
        raise Http404("The frontend is not built here (previews serve it with Vite).")
    return FileResponse(open(index, "rb"), content_type="text/html")


def media(request, path):
    """An upload (PX.269): served for a link this server signed within the hour (only a caller who may read the
    record holding it gets one), or when a record anyone may read holds it (a dish photo); otherwise 404."""
    if not _signed(path, request.GET.get('s', '')) and not _public(path):
        raise Http404
    return serve(request, path, document_root=settings.MEDIA_ROOT)


def _signed(path, token):
    if not token:
        return False
    try:
        from config.storage import link_is_signed
    except ImportError:
        return False
    return link_is_signed(path, token)


def _public(path):
    """True when a record a visitor may read holds this file."""
    from django.apps import apps
    from django.contrib.auth.models import AnonymousUser
    try:
        from api import access
    except ImportError:
        access = None
    for model in apps.get_app_config('api').get_models():
        for field in model._meta.concrete_fields:
            if field.get_internal_type() not in ('FileField', 'ImageField'):
                continue
            rows = model._default_manager.filter(**{field.name: path})
            if rows.exists() if access is None else access.scope(AnonymousUser(), model.__name__, rows).exists():
                return True
    return False


urlpatterns = [
    path('admin/', admin.site.urls),
    path('api/', include('api.urls')),
    path('health/', health_check, name='health'),
    re_path(r'^media/(?P<path>.*)$', media, name='media'),
    re_path(r'^(?!api/|admin/|health/|media/|static/).*$', frontend, name='frontend'),
]
